/// <summary>
/// Units of one item variant, to its inventory unit: 1 UnitId = Factor InventoryUnit.
/// </summary>
[DataContractAttribute]
class HSMobileOpsItemUnitsResult
{
    str itemId;
    str configId;
    str sizeId;
    str colorId;
    str styleId;
    str inventoryUnit;
    List units;

}

Method.Source:
